parameters.jsCode:
const body = $input.item.json.body || {};
const user_email = body.user_email || '';
const issue = body.issue || '';
const thread_id = body.thread_id || '';

if (!user_email || !issue) {
  throw new Error('Validation failed: user_email and issue are required');
}

const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g,'');
const rand = Math.random().toString(36).substring(2,8).toUpperCase();
const ticket_id = `TKT-${dateStr}-${rand}`;

return [{ json: { ticket_id, user_email, issue, thread_id } }];

const prevData = $('Validate Input').item.json;
const llmText = $input.item.json.text || '{}';

let classification;
try {
  const match = llmText.match(/\{[\s\S]*\}/);
  classification = JSON.parse(match ? match[0] : llmText);
} catch(e) {
  classification = {
    category: 'General',
    priority: 'medium',
    next_action: 'Review and assign to support team',
    assigned_team: 'General Support'
  };
}

return [{
  json: {
    ticket_id: prevData.ticket_id,
    user_email: prevData.user_email,
    issue: prevData.issue,
    category: classification.category || 'General',
    priority: classification.priority || 'medium',
    next_action: classification.next_action || 'Review and assign',
    assigned_team: classification.assigned_team || 'General Support'
  }
}];

